arguments.content:
@import url();

:root{--paper:#f4efdf;--ink:#243f3b;--muted:#6f7b6d;--line:#cbd0bd;--orange:#dc8551}
*{box-sizing:border-box}
html,body{margin:0;min-width:320px;background:var(--paper);color:var(--ink)}
body{font-family:Arial,Helvetica,sans-serif;-webkit-font-smoothing:antialiased}
body::after{content:"";position:fixed;inset:0;pointer-events:none;z-index:10;opacity:.045;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.88' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Cpath fill='%23000' filter='url(%23n)' opacity='.6' d='M0 0h180v180H0z'/%3E%3C/svg%3E")}
.page{width:100%;overflow:hidden;padding:0 4.2%;max-width:2000px;margin:auto}
.masthead{height:116px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);position:relative;z-index:3}
.brand{display:flex;gap:15px;align-items:center;text-decoration:none;color:inherit;font-family:Georgia,'Times New Roman',serif;font-size:31px;font-weight:700;letter-spacing:-1.2px;line-height:1.1;pointer-events:none}
.brand-mark{width:49px;height:49px;fill:none;stroke:var(--ink);stroke-width:2;stroke-linecap:round}
.brand-sub{display:block;margin-top:9px;font:8px Arial,Helvetica,sans-serif;letter-spacing:2px}
.header-note{font-size:10px;letter-spacing:2.2px;display:flex;align-items:center;gap:13px;margin-left:-18px}
.little-star{font-size:24px;font-weight:400;color:var(--orange)}
.weather{display:flex;gap:12px;align-items:center}
.weather>svg{height:31px;width:31px;fill:none;stroke:var(--ink);stroke-width:1.25}
.weather>span{font-family:Georgia,'Times New Roman',serif;font-size:25px;line-height:1}
.weather small{display:block;font:8px Arial,Helvetica,sans-serif;letter-spacing:1.4px;margin-top:7px}
.hero{height:calc(100svh - 265px);min-height:600px;max-height:900px;position:relative;isolation:isolate}
#scene{position:absolute;left:27%;right:-6%;top:0;bottom:-7px;z-index:1;pointer-events:none}
#scene canvas{display:block;width:100%;height:100%;outline:none}
.intro{position:relative;z-index:2;top:13.8%;width:43%;pointer-events:none}
.eyebrow{font-size:9px;letter-spacing:2.5px;display:flex;align-items:center;gap:10px;font-weight:500}
.eyebrow>span{display:block;width:18px;height:1px;background:var(--orange)}
h1{font-family:Georgia,'Times New Roman',serif;font-weight:400;font-size:clamp(83px,8.9vw,150px);letter-spacing:-7px;line-height:.91;margin:33px 0 29px;position:relative;width:fit-content}
h1 em{font-weight:400;letter-spacing:-7.5px}
.title-spark{font-family:Georgia,serif;position:absolute;color:var(--orange);font-size:39px;right:-51px;top:59%;font-style:normal;line-height:1}
.intro p{font-size:13px;line-height:1.85;letter-spacing:.15px;color:#647367;margin:0}
.slow-note{margin-top:33px;font-family:Georgia,'Times New Roman',serif;font-style:italic;font-size:15px;display:flex;align-items:center;gap:13px;color:#667367}
.note-line{width:29px;height:1px;background:#aeb8a5}
.sun-stamp{position:absolute;left:76.5%;width:180px;top:6.4%;z-index:0;transform:rotate(-15deg)}
.sun-stamp>svg{display:block;width:100%;overflow:visible}
.sun-fill{fill:#edbc7d}
.sun-lettering{font-size:10px;letter-spacing:2.3px;fill:#84643e;font-family:Arial,Helvetica,sans-serif;transform-origin:110px 110px;animation:orbit 100s linear infinite}
.sun-wave,.sun-spark{fill:none;stroke:#b78046;stroke-width:2;stroke-linecap:round}
.distant-birds{position:absolute;left:47%;top:8%;width:190px;opacity:.5;z-index:0;animation:float 8s ease-in-out infinite}
.distant-birds svg{fill:none;stroke:#738c7e;stroke-width:1.6;stroke-linecap:round;width:100%}
.scene-caption{position:absolute;right:.4%;top:42%;z-index:2;color:#718372;transform:rotate(8deg);pointer-events:none}
.scene-caption span{display:block;font-family:Georgia,'Times New Roman',serif;font-style:italic;font-size:19px;line-height:1.25}
.scene-caption svg{width:65px;height:56px;fill:none;stroke:#829080;stroke-width:1.2;transform:rotate(30deg);margin:7px 0 0 -18px}
.live-label{position:absolute;bottom:27px;left:0;z-index:2;display:flex;align-items:center;gap:8px;font-size:8px;letter-spacing:1.6px}
.live-dot{height:6px;width:6px;border-radius:50%;background:#6f9e79;box-shadow:0 0 0 4px #6f9e7911;animation:breathe 3s ease-in-out infinite}
.live-time{font-size:18px;line-height:8px;margin-left:6px;color:#889381;font-family:Georgia,serif}
.edition{position:absolute;bottom:29px;right:0;font-size:8px;letter-spacing:1.5px;z-index:2;color:#738173}
.edition>span{margin:0 9px;color:#a7af9a}
.forecast{position:relative;z-index:2;min-height:104px;display:flex;align-items:center;justify-content:space-between;border-top:1px solid var(--line);border-bottom:1px solid var(--line);gap:20px}
.forecast-heading{display:flex;align-items:center;gap:13px;min-width:190px}
.forecast-heading>svg{width:38px;height:30px;fill:none;stroke:var(--ink);stroke-width:1.5;stroke-linecap:round}
.forecast-heading>span{font-size:9px;line-height:1.6;letter-spacing:1.7px}
.forecast-heading strong{font-weight:500}
.condition{display:flex;flex-direction:column;gap:12px}
.condition>span{font-size:8px;color:#758173;letter-spacing:1.7px}
.condition>strong{display:flex;align-items:center;gap:13px;font-family:Georgia,'Times New Roman',serif;font-size:16px;font-weight:400;white-space:nowrap}
.condition strong svg{width:23px;height:17px;fill:none;stroke:#8a9782;stroke-width:1.2;overflow:visible}
.mini-wave{font-size:26px;color:#8a9782;line-height:14px}
.mini-star{font-size:19px;color:#b48d5e;line-height:14px}
.footer-signoff{font-family:Georgia,'Times New Roman',serif;font-style:italic;font-size:16px;display:flex;align-items:center;gap:17px;margin-left:20px}
.footer-signoff svg{width:32px;fill:none;stroke:#8a9782;stroke-width:1}
.bottom-line{height:45px;display:flex;align-items:center;justify-content:space-between;font-size:7px;letter-spacing:1.5px;color:#84907d}
.small-sun{font-size:17px;line-height:7px;margin-left:9px;vertical-align:middle}
@keyframes orbit{to{transform:rotate(360deg)}}
@keyframes float{50%{transform:translate(7px,-5px)}}
@keyframes breathe{50%{opacity:.5;box-shadow:0 0 0 5px #6f9e7908}}
@media(min-width:1700px){.hero{min-height:710px}.intro{top:17%}.sun-stamp{width:210px}}
@media(max-width:1100px){.page{padding:0 4%}.masthead{height:100px}.hero{height:calc(100svh - 249px);min-height:580px}h1{font-size:105px;letter-spacing:-6px}h1 em{letter-spacing:-6px}.header-note{font-size:8px;letter-spacing:1.5px;margin-left:0}.brand{font-size:27px}.brand-sub{font-size:7px}.intro{top:15%}.sun-stamp{width:145px;left:78%;top:9%}.scene-caption{right:-1%;font-size:16px;top:40%}.scene-caption span{font-size:16px}.forecast-heading{min-width:145px;gap:8px}.forecast-heading>span{font-size:8px}.forecast-heading>svg{width:30px}.condition>strong{font-size:14px;gap:8px}.footer-signoff{font-size:14px;max-width:150px;gap:8px;margin-left:0}.footer-signoff svg{min-width:25px}.eyebrow{font-size:8px;letter-spacing:1.8px}.edition{font-size:7px;letter-spacing:1px}.live-label{font-size:7px;letter-spacing:1px}.intro p{font-size:12px}.slow-note{font-size:13px}}
@media(max-width:760px){.page{padding:0 6%}.masthead{height:91px}.brand{font-size:25px;gap:10px}.brand-mark{width:40px;height:40px}.brand-sub{font-size:6px;letter-spacing:1.6px;margin-top:7px}.header-note{display:none}.weather>span{font-size:21px}.weather>svg{width:25px;height:25px}.weather small{font-size:6px;letter-spacing:1px}.hero{min-height:805px;height:calc(100svh - 235px);max-height:950px}.intro{top:41px;width:100%}.eyebrow{font-size:8px;letter-spacing:1.7px}h1{font-size:91px;letter-spacing:-5px;margin:25px 0 19px;line-height:.9}h1 em{letter-spacing:-5px}.title-spark{font-size:30px;right:-39px}.intro p{font-size:12px;line-height:1.8}.slow-note{display:none}#scene{left:-27%;right:-25%;top:270px;bottom:27px}.sun-stamp{left:auto;right:2%;top:202px;width:120px}.distant-birds{left:58%;top:86px;width:120px}.scene-caption{top:413px;right:0}.scene-caption span{font-size:14px}.scene-caption svg{height:45px;width:50px}.live-label{bottom:23px;font-size:6px;letter-spacing:1.2px}.edition{display:none}.forecast{display:grid;grid-template-columns:1fr 1fr 1fr;gap:22px 10px;padding:23px 0;min-height:130px}.forecast-heading{grid-column:1/-1;min-width:0;gap:9px}.forecast-heading>span{display:flex;gap:5px;font-size:8px}.forecast-heading>svg{height:19px;width:27px}.forecast-heading br{display:none}.condition{gap:9px}.condition>span{font-size:6px;letter-spacing:1px}.condition>strong{font-size:12px;gap:5px}.condition>strong svg{width:17px}.mini-star{font-size:15px}.mini-wave{font-size:21px}.footer-signoff{display:none}.bottom-line{height:42px;font-size:5.5px;letter-spacing:.9px}.small-sun{font-size:13px;margin-left:4px}}
@media(prefers-reduced-motion:reduce){.sun-lettering,.distant-birds,.live-dot{animation:none}}

import * as THREE from 'three';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';

// An entirely procedural little seaside escape. No models, textures, or network requests.
const container = document.querySelector('#scene');
const scene = new THREE.Scene();
const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setClearColor(0x000000, 0);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.18;
container.appendChild(renderer.domElement);

const camera = new THREE.OrthographicCamera(-8, 8, 5, -5, 0.1, 100);
camera.position.set(8.5, 7.2, 16.5);
camera.lookAt(0, 1.9, 0);
const pmrem = new THREE.PMREMGenerator(renderer);
const studio = new RoomEnvironment();
scene.environment = pmrem.fromScene(studio, 0.04).texture;
scene.environmentIntensity = 0.32;
studio.dispose();
pmrem.dispose();

scene.add(new THREE.HemisphereLight(0xfff8de, 0x509589, 2.1));
const sunlight = new THREE.DirectionalLight(0xfff0cf, 3.3);
sunlight.position.set(-7, 12, 7);
sunlight.castShadow = true;
sunlight.shadow.mapSize.set(2048, 2048);
sunlight.shadow.camera.left = -11;
sunlight.shadow.camera.right = 11;
sunlight.shadow.camera.top = 10;
sunlight.shadow.camera.bottom = -8;
sunlight.shadow.normalBias = 0.035;
sunlight.shadow.bias = -0.0001;
sunlight.shadow.radius = 4;
scene.add(sunlight);
const rimLight = new THREE.DirectionalLight(0xd9fff0, 1.8);
rimLight.position.set(5, 7, -8);
scene.add(rimLight);

function mat(color, roughness = 0.65, extra = {}) {
  return new THREE.MeshStandardMaterial({ color, roughness, ...extra });
}
const cream = mat('#fff8e4');
const featherLight = mat('#f6efda');
const featherShade = mat('#e2e3cd');
const graphite = mat('#304e4b');
const featherMid = mat('#65796d');
const gold = mat('#f9b641', 0.42);
const pouchMat = mat('#eaaa42', 0.65);
const orange = mat('#df8a35', 0.52);
const coral = mat('#dd6f4d', 0.4);
const foamMat = mat('#f3f7e3', 0.65);
const paleFoam = mat('#caedda', 0.55);
const sphereGeo = new THREE.SphereGeometry(1, 32, 24);
const dropGeo = new THREE.SphereGeometry(1, 12, 10);

function ellipsoid(parent, material, pos, scale, rotation = 0) {
  const mesh = new THREE.Mesh(sphereGeo, material);
  mesh.position.set(...pos);
  mesh.scale.set(...scale);
  mesh.rotation.z = rotation;
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  parent.add(mesh);
  return mesh;
}
function curveMesh(parent, points, radius, material, segments = 40) {
  const curve = new THREE.CatmullRomCurve3(points.map(p => new THREE.Vector3(...p)));
  const mesh = new THREE.Mesh(new THREE.TubeGeometry(curve, segments, radius, 8, false), material);
  parent.add(mesh);
  return mesh;
}
function feather(parent, a, b, width, material, thickness = 0.07) {
  const start = new THREE.Vector3(...a);
  const end = new THREE.Vector3(...b);
  const length = start.distanceTo(end);
  const m = new THREE.Mesh(sphereGeo, material);
  m.position.copy(start.add(end).multiplyScalar(0.5));
  m.scale.set(width, thickness, length * 0.65);
  const direction = new THREE.Vector3(...b).sub(new THREE.Vector3(...a)).normalize();
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), direction);
  m.castShadow = true;
  m.receiveShadow = true;
  parent.add(m);
  return m;
}
function seededRandom(seed) {
  return () => {
    seed = (seed * 1664525 + 1013904223) >>> 0;
    return seed / 4294967296;
  };
}
const rand = seededRandom(181);

// Soft, transparent contact shadows keep the illustration floating on the paper.
const shadowCanvas = document.createElement('canvas');
shadowCanvas.width = shadowCanvas.height = 128;
const shadowCtx = shadowCanvas.getContext('2d');
const shadowGradient = shadowCtx.createRadialGradient(64, 64, 3, 64, 64, 64);
shadowGradient.addColorStop(0, 'rgba(35,76,65,.23)');
shadowGradient.addColorStop(0.45, 'rgba(35,76,65,.11)');
shadowGradient.addColorStop(1, 'rgba(35,76,65,0)');
shadowCtx.fillStyle = shadowGradient;
shadowCtx.fillRect(0, 0, 128, 128);
const shadowTexture = new THREE.CanvasTexture(shadowCanvas);
const groundShadow = new THREE.Mesh(new THREE.PlaneGeometry(21, 12), new THREE.MeshBasicMaterial({ map: shadowTexture, transparent: true, depthWrite: false }));
groundShadow.rotation.x = -Math.PI / 2;
groundShadow.position.set(0.4, -0.52, 0.4);
scene.add(groundShadow);

// A gently undulating, rounded patch of ocean, like a small sculpted world.
const seaGroup = new THREE.Group();
seaGroup.position.x = 0.1;
scene.add(seaGroup);
const rings = 34;
const sectors = 144;
const oceanPositions = [];
const oceanColors = [];
const oceanIndices = [];
const waterCenter = new THREE.Color('#29b1a9');
const waterEdge = new THREE.Color('#a1d8be');
const waterDeep = new THREE.Color('#159a99');
function seaHeight(x, z, t = 0) {
  return -0.12 + Math.sin(x * 1.1 + z * 0.8 + t * 0.9) * 0.045 + Math.cos(z * 1.7 - x * 0.4 + t * 0.7) * 0.035;
}
for (let r = 0; r <= rings; r++) {
  const u = r / rings;
  for (let j = 0; j <= sectors; j++) {
    const a = (j / sectors) * Math.PI * 2;
    const irregular = 1 + Math.sin(a * 3 + 0.5) * 0.035 + Math.sin(a * 7) * 0.018;
    const x = Math.cos(a) * 8.15 * u * irregular;
    const z = Math.sin(a) * 4.8 * u * irregular;
    const y = seaHeight(x, z) - Math.pow(u, 18) * 0.2;
    oceanPositions.push(x, y, z);
    const color = waterCenter.clone().lerp(waterEdge, Math.pow(u, 4) * 0.95);
    color.lerp(waterDeep, (Math.sin(x * 0.7 + z * 1.1) + 1) * 0.1 * (1 - u));
    oceanColors.push(color.r, color.g, color.b);
    if (r < rings && j < sectors) {
      const i = r * (sectors + 1) + j;
      oceanIndices.push(i, i + sectors + 1, i + 1, i + 1, i + sectors + 1, i + sectors + 2);
    }
  }
}
const oceanGeo = new THREE.BufferGeometry();
oceanGeo.setAttribute('position', new THREE.Float32BufferAttribute(oceanPositions, 3));
oceanGeo.setAttribute('color', new THREE.Float32BufferAttribute(oceanColors, 3));
oceanGeo.setIndex(oceanIndices);
oceanGeo.computeVertexNormals();
const ocean = new THREE.Mesh(oceanGeo, new THREE.MeshPhysicalMaterial({ vertexColors: true, roughness: 0.29, metalness: 0.02, clearcoat: 0.55, clearcoatRoughness: 0.3, side: THREE.DoubleSide }));
ocean.receiveShadow = true;
seaGroup.add(ocean);

// The wave is a thick, curling sheet, not a stock model. Its cross-section rolls over itself.
const waveGroup = new THREE.Group();
waveGroup.position.set(0.6, -0.06, -1.3);
seaGroup.add(waveGroup);
function wavePoint(u, v, offset = 0) {
  const x = -6.4 + u * 13.0;
  const envelope = Math.pow(Math.sin(Math.PI * u), 0.65);
  const radius = 0.12 + 2.28 * envelope;
  const maxAngle = 2.78 - 0.55 * Math.pow(1 - u, 1.5);
  const angle = -Math.PI / 2 + (maxAngle + Math.PI / 2) * v;
  const r = radius + offset;
  const y = radius + Math.sin(angle) * r - 0.06;
  const z = -Math.cos(angle) * r + Math.sin(u * Math.PI) * 0.25;
  return new THREE.Vector3(x, y, z);
}
const wx = 128;
const wv = 64;
const wavePos = [];
const waveCol = [];
const waveInd = [];
const lowColor = new THREE.Color('#087f82');
const midColor = new THREE.Color('#23b5b1');
const topColor = new THREE.Color('#8edac5');
for (let side = 0; side < 2; side++) {
  for (let i = 0; i <= wx; i++) {
    for (let j = 0; j <= wv; j++) {
      const u = i / wx;
      const v = j / wv;
      const p = wavePoint(u, v, side === 0 ? -0.015 : 0.14);
      wavePos.push(p.x, p.y, p.z);
      const c = lowColor.clone().lerp(midColor, Math.min(1, v * 1.6));
      c.lerp(topColor, Math.pow(v, 3) * 0.9);
      if (side === 0) c.multiplyScalar(0.93);
      const streak = Math.sin(u * 119 + v * 8) * Math.sin(u * 27 - v * 3) * 0.035;
      c.multiplyScalar(1 + streak);
      waveCol.push(c.r, c.g, c.b);
      if (i < wx && j < wv) {
        const k = side * (wx + 1) * (wv + 1) + i * (wv + 1) + j;
        if (side === 0) waveInd.push(k, k + 1, k + wv + 1, k + 1, k + wv + 2, k + wv + 1);
        else waveInd.push(k, k + wv + 1, k + 1, k + 1, k + wv + 1, k + wv + 2);
      }
    }
  }
}
const layerLength = (wx + 1) * (wv + 1);
for (let i = 0; i < wx; i++) {
  const a = i * (wv + 1) + wv;
  const b = (i + 1) * (wv + 1) + wv;
  waveInd.push(a, b, a + layerLength, b, b + layerLength, a + layerLength);
}
const waveGeo = new THREE.BufferGeometry();
waveGeo.setAttribute('position', new THREE.Float32BufferAttribute(wavePos, 3));
waveGeo.setAttribute('color', new THREE.Float32BufferAttribute(waveCol, 3));
waveGeo.setIndex(waveInd);
waveGeo.computeVertexNormals();
const wave = new THREE.Mesh(waveGeo, new THREE.MeshPhysicalMaterial({ vertexColors: true, roughness: 0.3, metalness: 0.025, clearcoat: 0.75, clearcoatRoughness: 0.24, side: THREE.DoubleSide }));
wave.castShadow = true;
wave.receiveShadow = true;
waveGroup.add(wave);

// Long engraved threads of water follow the inside of the barrel.
const waterLineMat = mat('#99dfcb', 0.42, { transparent: true, opacity: 0.38 });
const darkLineMat = mat('#187f84', 0.45, { transparent: true, opacity: 0.3 });
for (let i = 0; i < 31; i++) {
  const u = 0.055 + i / 34;
  const start = 0.11 + rand() * 0.22;
  const end = 0.79 + rand() * 0.18;
  const points = [];
  for (let j = 0; j <= 35; j++) {
    const v = start + (end - start) * j / 35;
    const p = wavePoint(u + Math.sin(v * 5 + i) * 0.005, v, -0.033);
    points.push(p.toArray());
  }
  curveMesh(waveGroup, points, 0.009 + rand() * 0.011, i % 4 === 0 ? darkLineMat : waterLineMat, 35);
}
for (let j = 0; j < 5; j++) {
  const points = [];
  for (let i = 0; i <= 70; i++) {
    const u = 0.08 + 0.85 * i / 70;
    const p = wavePoint(u, 0.84 + j * 0.025, 0.158);
    points.push(p.toArray());
  }
  curveMesh(waveGroup, points, j === 4 ? 0.04 : 0.018, j === 4 ? paleFoam : waterLineMat, 80);
}

const crestPoints = [];
for (let i = 0; i <= 110; i++) crestPoints.push(wavePoint(0.015 + i / 110 * 0.97, 1, 0.055).toArray());
curveMesh(waveGroup, crestPoints, 0.1, paleFoam, 140);
const foamBlobs = [];
for (let i = 0; i < 260; i++) {
  const u = 0.014 + i / 260 * 0.97;
  const p = wavePoint(u, 0.983 + rand() * 0.025, 0.04 + rand() * 0.13);
  p.y += rand() * 0.05;
  const size = 0.045 + rand() * 0.12;
  const blob = new THREE.Mesh(dropGeo, i % 4 === 0 ? paleFoam : foamMat);
  blob.position.copy(p);
  blob.scale.set(size * 1.5, size * 0.65, size);
  waveGroup.add(blob);
  foamBlobs.push({ mesh: blob, y: p.y, phase: rand() * Math.PI * 2 });
}

// Water trails and lacy foam at the edges of the little sea.
const rippleMat = mat('#d7ecce', 0.6, { transparent: true, opacity: 0.72 });
const subtleRipple = mat('#b0e1c9', 0.4, { transparent: true, opacity: 0.6 });
const rippleGroups = [];
for (let k = 0; k < 21; k++) {
  const group = new THREE.Group();
  const a = rand() * Math.PI * 2;
  const r = 0.52 + rand() * 0.39;
  const x = Math.cos(a) * 7.4 * r;
  const z = Math.sin(a) * 4.5 * r;
  const points = [];
  const length = 0.45 + rand() * 1.2;
  for (let j = 0; j <= 16; j++) {
    const f = j / 16;
    const xx = x + (f - 0.5) * length;
    const zz = z + Math.sin(f * Math.PI) * 0.14;
    points.push([xx, seaHeight(xx, zz) + 0.035, zz]);
  }
  curveMesh(group, points, 0.009 + rand() * 0.012, k % 3 === 0 ? rippleMat : subtleRipple, 20);
  seaGroup.add(group);
  rippleGroups.push({ group, phase: rand() * Math.PI * 2 });
}
for (let k = 0; k < 9; k++) {
  const points = [];
  for (let j = 0; j < 50; j++) {
    const a = 0.08 + j / 49 * 1.08;
    const r = 0.7 + k * 0.025;
