function resize() {
  const w=container.clientWidth;
  const h=container.clientHeight;
  renderer.setSize(w,h);
  const aspect=w/h;
  const viewHeight=window.innerWidth<=760?10.8:10.5;
  camera.left=-viewHeight*aspect/2;
